mapper.select:
SELECT MIN(schedule_date) FROM mrp_daily_plan_detail WHERE run_id=#{runId}
UNION SELECT MAX(schedule_date) FROM mrp_daily_plan_detail WHERE run_id=#{runId}
UNION SELECT MIN(o.schedule_date) FROM mrp_daily_plan_override o
WHERE o.batch_id=#{batchId} AND EXISTS (SELECT 1 FROM mrp_daily_plan_detail d WHERE d.run_id=#{runId}
  AND d.factory_code=o.factory_code AND d.root_material_code=o.root_material_code
  AND d.terminal_material_code=o.terminal_material_code AND d.terminal_type=o.terminal_type
  AND d.supply_mode=o.supply_mode AND d.path_group_key=o.path_group_key)
UNION SELECT MAX(o.schedule_date) FROM mrp_daily_plan_override o
WHERE o.batch_id=#{batchId} AND EXISTS (SELECT 1 FROM mrp_daily_plan_detail d WHERE d.run_id=#{runId}
  AND d.factory_code=o.factory_code AND d.root_material_code=o.root_material_code
  AND d.terminal_material_code=o.terminal_material_code AND d.terminal_type=o.terminal_type
  AND d.supply_mode=o.supply_mode AND d.path_group_key=o.path_group_key)

